-- Resources content for Bookings' first slice, the rate model (CLAUDE.md,
-- "Resources stay in step with the code"). Content only; the schema is
-- 20261005140000_bookings_foundation.sql.

select private.rc_release_guide(
  p_slug => 'bookings-rate-model',
  p_tool_key => 'bookings',
  p_title => 'The rate model',
  p_summary => 'Assumptions and their validation, resource pools, service packages, the rate card a partner sees, and adopting a version.',
  p_screen_keys => array['bookings.rates'],
  p_sort_order => 10,
  p_version_note => 'Rate model',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Rates","marks":[{"type":"bold"}]},{"type":"text","text":" tab holds the production rate model: what a studio half-day, an event webcast, a field day or an editing hour costs WUWF, and the rates on the card a partner sees. Everything on the card is computed from the assumptions; nothing is typed in by hand."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The version picker at the top switches between versions. One version is "},{"type":"text","text":"in use","marks":[{"type":"bold"}]},{"type":"text","text":" for estimates at a time. A version that has not been adopted is labelled provisional, and so is every figure from it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An adopted version never changes. To correct it, Finance selects "},{"type":"text","text":"New version","marks":[{"type":"bold"}]},{"type":"text","text":", which copies the chosen version's assumptions, pools and packages into a draft."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Assumptions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourced cost inputs","marks":[{"type":"bold"}]},{"type":"text","text":" are budget lines: the shared production pool, the webcasting pool and the university assessment. "},{"type":"text","text":"Working assumptions","marks":[{"type":"bold"}]},{"type":"text","text":" are the values the model needs that no budget states, such as the production lead's salary and fringe, student wages, the external margin, and the capacity placeholders."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each row names who must validate it and what that takes. Finance selects "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on a row to change its value on a draft, and "},{"type":"text","text":"Validated","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Accept as is","marks":[{"type":"bold"}]},{"type":"text","text":" to resolve it. Accepting as is asks for a note."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Derived","marks":[{"type":"bold"}]},{"type":"text","text":" panel shows the loaded hourly costs, the pool totals and the baseline capacity in days, recomputed from the rows above. "},{"type":"text","text":"What moves the price most","marks":[{"type":"bold"}]},{"type":"text","text":" re-runs the model with one input moved, so validation effort goes where it changes the card."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Resource pools and service packages"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource pools","marks":[{"type":"bold"}]},{"type":"text","text":" split the shared production pool across studio, field, live and edit, each with its available units a year. Cost per unit is the pool's share divided by its units."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Service packages","marks":[{"type":"bold"}]},{"type":"text","text":" state what each package assumes: professional and student hours, units of each pool, webcast operations, and the external market floor. The strategic cost is student labor plus resources plus webcast operations; the incremental cost adds professional hours at the loaded rate."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The rate card"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every rate rounds up to the next $25. The external rate is the higher of the incremental cost grossed up for the margin and the assessment, and the package's market floor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strategic internal applies only to qualifying university work charged against the baseline envelope; incremental internal to ordinary partner-directed work; external to outside clients when open capacity exists."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record for estimates","marks":[{"type":"bold"}]},{"type":"text","text":" saves the card as computed, so an estimate priced later keeps the rate it was priced at. "},{"type":"text","text":"Print","marks":[{"type":"bold"}]},{"type":"text","text":" prints the card alone."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Adopting a version"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Finance resolves every assumption and pool, then selects "},{"type":"text","text":"Submit for validation","marks":[{"type":"bold"}]},{"type":"text","text":". A version with anything still pending cannot be submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Executive Director selects "},{"type":"text","text":"Adopt","marks":[{"type":"bold"}]},{"type":"text","text":", recording the Budget/Controller's destination index for recoveries. The previous adopted version is superseded, and the new one is in use."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Change log","marks":[{"type":"bold"}]},{"type":"text","text":" lists who changed what on each version."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'bookings-asset-inventory',
  p_tool_key => 'bookings',
  p_title => 'Asset inventory',
  p_summary => 'The major production assets by pool, cost, funding source, useful life, restrictions and condition.',
  p_screen_keys => array['bookings.assets'],
  p_sort_order => 20,
  p_version_note => 'Asset inventory',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Rates","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Assets","marks":[{"type":"bold"}]},{"type":"text","text":" lists the major studio, field, live-production and post-production assets: acquisition cost and date, funding source, useful life, restrictions, maintenance burden and condition. Finance or the Director of Operations keeps it."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ New asset","marks":[{"type":"bold"}]},{"type":"text","text":" to add one, or an asset's name to edit it. Filter by pool or by funding source with the chips."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Equipment funded by the Foundation, members or a restricted grant is not prepaid institutional capacity. Note the restriction on the asset, such as public-service use only."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The pool costs in the rate model stay the budget-line allocation until this inventory, with UWF Budget/Controller's cost-recovery treatment for each asset, replaces it in a new rate model version. Nothing here changes a rate on its own."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An asset that leaves service is marked out of service, not deleted."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-05-bookings-rate-model',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-05',
  p_title => 'Bookings: the rate model',
  p_guide_slugs => array['bookings-rate-model', 'bookings-asset-inventory'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings is a new tool for university production work. Its first part is the rate model that replaces the v0.1 workbook: sourced cost inputs and working assumptions, each with who must validate it; the four resource pools; the service packages and what each assumes; the rate card a partner sees, computed from the assumptions and rounded up to the next $25; and an asset inventory. Version v0.1 is in use provisionally. Finance validates each assumption and submits a version, and the Executive Director adopts it."}]}]}$body$
);
